#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

int main() {
    struct Node *head = NULL;
    for (int v = 3; v >= 1; v--) {
        struct Node *node = malloc(sizeof(struct Node));
        node->value = v * 10;
        node->next = head;
        head = node;
    }
    for (struct Node *p = head; p != NULL; p = p->next) {
        printf("%d -> ", p->value);
    }
    printf("NULL\n");
    return 0;
}
